void setup() {
  // Инициализируем пин 13 как выход
  pinMode(13, OUTPUT);
}

void loop() {
  digitalWrite(13, HIGH);  // Включаем светодиод (подаём 5 В)
  delay(1000);              // Ждём 1 секунду
  digitalWrite(13, LOW);    // Выключаем светодиод (0 В)
  delay(1000);              // Ждём 1 секунду
}
